52	void lcpu_rom_config_default(void)
53	{
54	  uint8_t is_enable_lxt;
55	
56	  syslog(LOG_INFO, "sf32lb58 lcpu_boot: lcpu_rom_config_default\n");
57	  uint8_t is_lcpu_rccal = 0;
58	  uint32_t wdt_staus = 0xFF;
59	  uint32_t wdt_time = 10;
60	  uint16_t wdt_clk = 32768;
61	
62	  if (HAL_LXT_DISABLED())
63	    {
64	      is_lcpu_rccal = 1;
65	    }
66	
67	  is_enable_lxt = 1 - is_lcpu_rccal;
68	  HAL_LCPU_CONFIG_set(HAL_LCPU_CONFIG_XTAL_ENABLED, &is_enable_lxt, 1);
69	  HAL_LCPU_CONFIG_set(HAL_LCPU_CONFIG_WDT_STATUS, &wdt_staus, 4);
70	  HAL_LCPU_CONFIG_set(HAL_LCPU_CONFIG_WDT_TIME, &wdt_time, 4);
71	  HAL_LCPU_CONFIG_set(HAL_LCPU_CONFIG_WDT_CLK_FEQ, &wdt_clk, 2);
72	  HAL_LCPU_CONFIG_set(HAL_LCPU_CONFIG_BT_RC_CAL_IN_L, &is_lcpu_rccal, 1);
73	
74	  {
75	    uint32_t tx_queue = HCPU2LCPU_MB_CH1_BUF_START_ADDR;
76	    hal_lcpu_bluetooth_rom_config_t config = {0};
77	    hal_lcpu_ble_mem_config_t ble_config = {0};
78	
79	    config.bit_valid |= 1 << 10 | 1 << 6 | 1 << 2;
80	    config.lld_prog_delay = 3;
81	    config.is_fpga = 0;
82	    config.default_xtal_enabled = is_enable_lxt;
83	    HAL_LCPU_CONFIG_set(HAL_LCPU_CONFIG_HCPU_TX_QUEUE, &tx_queue, 4);
84	    HAL_LCPU_CONFIG_set(HAL_LCPU_CONFIG_BT_CONFIG, &config, sizeof(config));
85	
86	    ble_config.max_nb_of_hci_completed = 6;
87	    ble_config.bit_valid = 1 << 6;
88	    HAL_LCPU_CONFIG_set(HAL_LCPU_CONFIG_BT_KE_BUF,
89	                        &ble_config, sizeof(ble_config));
90	  }
91	}
