121	uint8_t lcpu_power_on(void)
122	{
123	  syslog(LOG_INFO, "sf32lb58 lcpu_boot: start\n");
124	  HAL_HPAON_WakeCore(CORE_ID_LCPU);
125	  HAL_RCC_Reset_and_Halt_LCPU(0);
126	
127	  lcpu_nvds_config();
128	  syslog(LOG_INFO, "sf32lb58 lcpu_boot: rom_config\n");
129	  lcpu_rom_config();
130	  syslog(LOG_INFO, "sf32lb58 lcpu_boot: clean config 0x%08x len=%d\n",
131	         (unsigned int)LCPU_CONFIG_START_ADDR,
132	         (int)LCPU_CONFIG_get_total_size());
133	  sf32lb58_lcpu_boot_clean_range(LCPU_CONFIG_START_ADDR,
134	                                 LCPU_CONFIG_get_total_size());
135	
136	  if (HAL_RCC_GetHCLKFreq(CORE_ID_LCPU) > 24000000)
137	    {
138	      HAL_RCC_LCPU_SetDiv(2, 1, 5);
139	    }
140	
141	  syslog(LOG_INFO, "sf32lb58 lcpu_boot: installing img\n");
142	  lcpu_img_install();
143	
144	  syslog(LOG_INFO, "sf32lb58 lcpu_boot: config start addr 0x%08x\n",
145	         (unsigned int)HCPU_LCPU_CODE_START_ADDR);
146	  HAL_LPAON_ConfigStartAddr((uint32_t *)HCPU_LCPU_CODE_START_ADDR);
147	  lcpu_ble_patch_install();
148	  HAL_RCC_ReleaseLCPU();
149	  /* Do NOT call HAL_HPAON_CANCEL_LP_ACTIVE_REQUEST() here.
150	   * The bus bridge must stay active for ipc_queue_open() in
151	   * sf32lb58_bt_controller_enable().  It will be cancelled there.
152	   */
153	  HAL_Delay_us(5000);
154	  syslog(LOG_INFO, "sf32lb58 lcpu_boot: done\n");
155	  return 0;
156	}
