50	static void hcpu2lcpu_notification_callback(MAILBOX_HandleTypeDef *hmailbox, uint8_t q_idx)
51	{
52	    SF_ASSERT(q_idx < IPC_HW_QUEUE_NUM);
53	
54	    /* BLE code in ROM still use old ipc_queue implementation in ROM,
55	     i.e.
56	        BLE: rom_ipc_queue.c->rom_ipc_hw->rom_ipc_hw_obj
57	        User code in RAM: ram_ipc_queue.c->rom_ipc_hw->rom_ipc_hw_obj
58	        HCPU2LCPU_IRQHandler in RAM: notification_callback in RAM
59	            if (ble queue)
60	            {
61	                rom_ipc_queue_data_ind
62	            }
63	            else
64	            {
65	                ram_ipc_queue_data_ind
66	            }
67	
68	    new implementation in RAM changes the ipc_queue handle value range
69	    compared to old implementation in ROM,
70	    i.e.
71	    ROM: ipc_queue invalid handle is -1, valid handle starts from 0
72	    RAM: ipc_queue invalid handle is 0, valid handle starts from 10
73	    */
74	    if (ipc_hw_obj.ch[0].data.act_bitmap & (1UL << q_idx))
75	    {
76	        if (q_idx == 0)  /* the first queue is used by ble, it uses ROM implementation instead */
77	            ipc_queue_data_ind_rom(ipc_hw_obj.ch[0].data.user_data[q_idx]);
78	        else  /* other queue use RAM implementation */
79	            ipc_queue_data_ind(ipc_hw_obj.ch[0].data.user_data[q_idx]);
80	    }
81	}
